namespace sv_cb2a63477df54eaeb05bfe7357c3765c.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Memphis, TN",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "Online", new DateTimeOffset(2026, 7, 1, 10, 0, 0, TimeSpan.Zero)),
                new("Picked Up", "Seattle, WA", new DateTimeOffset(2026, 7, 1, 18, 30, 0, TimeSpan.Zero)),
                new("In Transit", "Memphis, TN", new DateTimeOffset(2026, 7, 2, 22, 15, 0, TimeSpan.Zero))
            }),

        ["PKG-002"] = new Shipment(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 2, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "Online", new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero)),
                new("Shipped", "Portland, OR", new DateTimeOffset(2026, 6, 28, 16, 0, 0, TimeSpan.Zero)),
                new("In Transit", "Dallas, TX", new DateTimeOffset(2026, 6, 30, 11, 0, 0, TimeSpan.Zero)),
                new("Out for Delivery", "Austin, TX", new DateTimeOffset(2026, 7, 2, 8, 0, 0, TimeSpan.Zero)),
                new("Delivered", "Austin, TX", new DateTimeOffset(2026, 7, 2, 11, 45, 0, TimeSpan.Zero))
            }),

        ["PKG-003"] = new Shipment(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Warehouse - Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 8, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "Online", new DateTimeOffset(2026, 7, 2, 14, 30, 0, TimeSpan.Zero)),
                new("Processing", "Warehouse - Chicago, IL", new DateTimeOffset(2026, 7, 2, 15, 0, 0, TimeSpan.Zero))
            })
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

using System.Net.Http.Json;
using sv_cb2a63477df54eaeb05bfe7357c3765c.Client.Models;

namespace sv_cb2a63477df54eaeb05bfe7357c3765c.Client.Services;

public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct)
            ?? throw new InvalidOperationException("Failed to deserialize shipment response.");
    }
}

